int heartbeat(const uint8_t *rec, size_t rec_len, uint8_t *out) {
    if (rec_len < 3) return -1;
    uint16_t payload_len = (rec[1] << 8) | rec[2];
    if ((size_t)payload_len + 3 > rec_len)
