MAX_TOTAL, MAX_FILES = 200 * 1024 * 1024, 1000

def read_bundle(z: zipfile.ZipFile):
    if len(z.infolist()) > MAX_FILES:
        raise ValueError("too many entries")
    total = 0
    for info in z.infolist():
        with z.open(info) as f:              # stream, never trust header sizes
            while chunk := f.read(65536):
                total += len(chunk)
                if total > MAX_TOTAL:
                    raise ValueError("archive expands too large")

