MAX_DEPTH = 64

def count_nodes(root):
    total, stack = 0, [(root, 0)]
    while stack:
        node, depth = stack.pop()
        if depth > MAX_DEPTH:
            raise ValueError("tree too deep")
        total += 1
        stack.extend((c, depth + 1) for c in node.get("children", []))
    return total

